import { BaseMandiProvider } from './base.provider.js';

/**
 * MockMandiProvider
 * Provides structured, verified reference sample market data for local development,
 * testing, and initial pipeline verification.
 *
 * IMPORTANT:
 * All records generated by this provider are explicitly tagged with:
 *   source: 'MOCK_PROVIDER'
 *   is_sample_data: true
 * This ensures that sample/demo data is NEVER presented as live real-world government records.
 */
export class MockMandiProvider extends BaseMandiProvider {
  constructor() {
    super('MOCK_PROVIDER');
  }

  /**
   * Generates a date string in YYYY-MM-DD format offset by `daysAgo` days.
   */
  #formatDate(daysAgo = 0) {
    const d = new Date();
    d.setDate(d.getDate() - daysAgo);
    return d.toISOString().split('T')[0];
  }

  /**
   * Fetches mock market data records
   * @param {Object} options - { state, commodity, days = 14, limit }
   */
  async fetchRecords(options = {}) {
    const targetDays = Math.min(options.days || 14, 30);
    const records = [];

    // Base market references
    const marketBases = [
      {
        mandi_name: 'Pune APMC (Gultekdi)',
        mandi_code: 'MH_PUNE_APMC',
        state: 'Maharashtra',
        district: 'Pune',
        market_center: 'Gultekdi',
        lat: 18.4967,
        lon: 73.8647,
        commodities: [
          { name: 'Onion', code: 'ONION', baseModal: 2450, spread: 250, arrivalBase: 420 },
          { name: 'Tomato', code: 'TOMATO', baseModal: 1850, spread: 200, arrivalBase: 310 },
          { name: 'Potato', code: 'POTATO', baseModal: 1600, spread: 150, arrivalBase: 500 },
          { name: 'Soybean', code: 'SOYBEAN', baseModal: 4650, spread: 180, arrivalBase: 180 },
        ],
      },
      {
        mandi_name: 'Nashik Market Yard',
        mandi_code: 'MH_NSK_MAIN',
        state: 'Maharashtra',
        district: 'Nashik',
        market_center: 'Panchavati',
        lat: 19.9975,
        lon: 73.7898,
        commodities: [
          { name: 'Onion', code: 'ONION', baseModal: 2350, spread: 220, arrivalBase: 650 },
          { name: 'Tomato', code: 'TOMATO', baseModal: 1720, spread: 190, arrivalBase: 410 },
          { name: 'Soybean', code: 'SOYBEAN', baseModal: 4580, spread: 210, arrivalBase: 220 },
          { name: 'Wheat', code: 'WHEAT', baseModal: 2850, spread: 120, arrivalBase: 320 },
        ],
      },
      {
        mandi_name: 'Ahmednagar Mandi',
        mandi_code: 'MH_AHM_APMC',
        state: 'Maharashtra',
        district: 'Ahmednagar',
        market_center: 'Market Yard',
        lat: 19.0952,
        lon: 74.7480,
        commodities: [
          { name: 'Onion', code: 'ONION', baseModal: 2380, spread: 200, arrivalBase: 380 },
          { name: 'Tomato', code: 'TOMATO', baseModal: 1690, spread: 160, arrivalBase: 250 },
          { name: 'Cotton', code: 'COTTON', baseModal: 7100, spread: 350, arrivalBase: 150 },
          { name: 'Soybean', code: 'SOYBEAN', baseModal: 4620, spread: 190, arrivalBase: 290 },
        ],
      },
      {
        mandi_name: 'Baramati APMC',
        mandi_code: 'MH_BAR_APMC',
        state: 'Maharashtra',
        district: 'Pune',
        market_center: 'Baramati',
        lat: 18.1519,
        lon: 74.5772,
        commodities: [
          { name: 'Onion', code: 'ONION', baseModal: 2320, spread: 180, arrivalBase: 240 },
          { name: 'Tomato', code: 'TOMATO', baseModal: 1780, spread: 180, arrivalBase: 210 },
          { name: 'Wheat', code: 'WHEAT', baseModal: 2800, spread: 100, arrivalBase: 190 },
        ],
      },
      {
        mandi_name: 'Mumbai APMC (Vashi)',
        mandi_code: 'MH_MUM_VASHI',
        state: 'Maharashtra',
        district: 'Thane',
        market_center: 'Vashi',
        lat: 19.0771,
        lon: 72.9986,
        commodities: [
          { name: 'Onion', code: 'ONION', baseModal: 2650, spread: 300, arrivalBase: 850 },
          { name: 'Tomato', code: 'TOMATO', baseModal: 2050, spread: 250, arrivalBase: 620 },
          { name: 'Potato', code: 'POTATO', baseModal: 1820, spread: 160, arrivalBase: 710 },
        ],
      },
      {
        mandi_name: 'Lasalgaon APMC',
        mandi_code: 'MH_NSK_LASALGAON',
        state: 'Maharashtra',
        district: 'Nashik',
        market_center: 'Lasalgaon',
        lat: 20.1472,
        lon: 74.2289,
        commodities: [
          { name: 'Onion', code: 'ONION', baseModal: 2280, spread: 240, arrivalBase: 950 },
          { name: 'Wheat', code: 'WHEAT', baseModal: 2790, spread: 110, arrivalBase: 280 },
        ],
      },
    ];

    // Filter by options if provided
    for (let dayOffset = 0; dayOffset < targetDays; dayOffset++) {
      const priceDate = this.#formatDate(dayOffset);

      for (const m of marketBases) {
        if (options.state && m.state.toLowerCase() !== options.state.toLowerCase()) continue;
        if (options.district && m.district.toLowerCase() !== options.district.toLowerCase()) continue;

        for (const c of m.commodities) {
          if (options.commodity && c.name.toLowerCase() !== options.commodity.toLowerCase() && c.code.toLowerCase() !== options.commodity.toLowerCase()) {
            continue;
          }

          // Deterministic drift to mimic genuine seasonal price action
          const dayFactor = Math.sin((dayOffset + 1) * 0.45);
          const modalPrice = Math.round(c.baseModal + dayFactor * (c.spread * 0.8));
          const minPrice = Math.round(modalPrice - (c.spread * 0.45));
          const maxPrice = Math.round(modalPrice + (c.spread * 0.55));
          const arrivals = Math.round(c.arrivalBase + dayFactor * (c.arrivalBase * 0.2));

          records.push({
            mandi_name: m.mandi_name,
            mandi_code: m.mandi_code,
            state: m.state,
            district: m.district,
            market_center: m.market_center,
            latitude: m.lat,
            longitude: m.lon,
            commodity_name: c.name,
            commodity_code: c.code,
            price_date: priceDate,
            min_price: minPrice,
            max_price: maxPrice,
            modal_price: modalPrice,
            arrivals_quantity: arrivals,
            unit: 'quintal',
            variety: 'Local/FAQ',
            grade: 'FAQ',
            source: 'MOCK_PROVIDER',
            is_sample_data: true,
          });
        }
      }
    }

    if (options.limit && options.limit > 0) {
      return records.slice(0, options.limit);
    }

    return records;
  }
}

export default MockMandiProvider;
